import json,re
def num(x):
    try: return float(x)
    except: return None
def strict(s):
    sols=re.findall(r'#### (\-?[0-9\.\,]+)', s[-300:])
    if not sols: return None
    return sols[-1].replace(',','').replace('\$','')
def strict_all(s):
    sols=re.findall(r'#### (\-?[0-9\.\,]+)', s)
    if not sols: return None
    return sols[-1].replace(',','').replace('\$','')
def lastnum(s):
    m=re.findall(r'-?\d[\d,]*(?:\.\d+)?', s)
    if not m: return None
    return m[-1].replace(',','')
def boxed(s):
    m=re.findall(r'\\\\boxed\{([^}]*)\}', s)
    if not m: return None
    return m[-1]
def loose(s):
    return set(re.findall(r'-?\d[\d,]*(?:\.\d+)?', s))
for fn in ['val_generations/0.jsonl','val_generations/100.jsonl']:
    rows=[json.loads(l) for l in open(fn)]
    n=len(rows); res={}
    for name,f in [('strict300',strict),('strict_all',strict_all),('lastnum',lastnum),('boxed',boxed)]:
        c=0
        for r in rows:
            a=f(r['output']); g=num(str(r['gts']))
            if a is not None and num(str(a))==g: c+=1
        res[name]=c/n
    c=sum(1 for r in rows if num(str(r['gts'])) in [num(str(x)) for x in loose(r['output'])])
    res['loose_any']=c/n
    print(fn, {k:round(v,4) for k,v in res.items()})
"

